'use strict';
fetch('content.json?v=dff2aa37c77c').then(r=>{if(!r.ok)throw new Error('content');return r.json();}).then(chapters=>{const id=new URLSearchParams(location.search).get('chapter')||'00-reading';const index=chapters.findIndex(c=>c.id===id);if(index<0){document.getElementById('article').innerHTML='<h1>没有找到这个章节</h1><p>可以从左侧目录继续阅读，或<a href="index.html#chapters">回到首页目录</a>。</p>';}for(const c of chapters){const a=document.createElement('a');a.href='read.html?chapter='+c.id;a.textContent=c.title;a.classList.toggle('current',c.id===id);if(c.id===id)a.setAttribute('aria-current','page');document.getElementById('reader-nav').append(a);const o=document.createElement('option');o.value=c.id;o.textContent=c.title;o.selected=c.id===id;document.getElementById('reader-selector').append(o);}document.getElementById('reader-selector').addEventListener('change',e=>location.href='read.html?chapter='+e.target.value);if(index<0)return;const chapter=chapters[index];document.title=chapter.title+' · 衣着有名';document.getElementById('article').innerHTML=chapter.html;const page=document.getElementById('pagination');if(index>0){const prev=document.createElement('a');prev.href='read.html?chapter='+chapters[index-1].id;prev.textContent='← 上一篇 · '+chapters[index-1].title.split('｜').pop();page.append(prev);}else page.append(document.createElement('span'));if(index<chapters.length-1){const next=document.createElement('a');next.href='read.html?chapter='+chapters[index+1].id;next.textContent='下一篇 · '+chapters[index+1].title.split('｜').pop()+' →';page.append(next);}}).catch(()=>{document.getElementById('article').innerHTML='<h1>读本暂时未能载入</h1><p>请刷新重试，或<a href="fashion-atlas.pdf">下载完整 PDF</a>继续阅读。</p>';});
